import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem79 preserva identidade e preços operacionais sem preço editorial ou indicação universal',()=>{for(const [id,titulo] of [['GSeid2PryzC2aiQwnv3h','Purificador de Água Gelada Fria e Natural Elétrico Compacto Eletrônico placa Filtro refil 6 meses ou 3000l Painel Touch Bivolt Cinza PE12G Electrolux'],['GT9gxxxsfkbjOfDG2uIM','Perfume Vf Bloom Virginia Fonseca 75ml - Wepink Volume da unidade 75 mL'],['GzjyGVKcBkoiKgQEo4p9','Shampoo Redutor de Grisalhos Grecin Control GX Para Todas os Tons Cabelo 118ml']]){const p={id,titulo,preco:'159,99',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.comentario,/159[.,]99|R\$/);assert.doesNotMatch(x.pros,/todos os tons|garantid|água potável|resultado comprovado/i);}});
